<?php require __DIR__.'/../includes/bootstrap.php';require_admin();if(!artist_alley_ready())redirect('upgrade-artist-alley.php');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if(in_array($action,['approve','reject','pending'],true)){db()->prepare('UPDATE artist_profiles SET status=? WHERE id=?')->execute([$action==='approve'?'approved':($action==='reject'?'rejected':'pending'),$id]);flash('success','Artist status updated.');}elseif($action==='feature'){db()->prepare('UPDATE artist_profiles SET is_featured=1-is_featured WHERE id=?')->execute([$id]);flash('success','Featured status updated.');}redirect('admin/artists.php');}$artists=db()->query('SELECT a.*,u.display_name,u.email,(SELECT COUNT(*) FROM artist_portfolio_items p WHERE p.artist_id=a.id) works FROM artist_profiles a JOIN users u ON u.id=a.user_id ORDER BY FIELD(a.status,\'pending\',\'approved\',\'draft\',\'rejected\'),a.created_at DESC')->fetchAll();app_header('Artist Admin');?>
<section class="dashboard-hero"><p class="eyebrow">ADMINISTRATION</p><h1>Artist Alley</h1><p>Approve artist profiles, select featured creators, and inspect portfolio readiness.</p></section><section class="app-card"><div class="table-wrap"><table><thead><tr><th>Artist</th><th>Owner</th><th>Status</th><th>Works</th><th>Commissions</th><th>Actions</th></tr></thead><tbody><?php foreach($artists as $a):?><tr><td><strong><?=e($a['artist_name'])?></strong><br><small><?=e($a['headline'])?></small></td><td><?=e($a['display_name'])?><br><small><?=e($a['email'])?></small></td><td><span class="badge"><?=e(ucfirst($a['status']))?></span><?=$a['is_featured']?' ★':''?></td><td><?=(int)$a['works']?></td><td><?=e(ucfirst($a['commission_status']))?></td><td><div class="inline-actions"><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$a['id']?>"><input type="hidden" name="action" value="<?=$a['status']==='approved'?'pending':'approve'?>"><button class="button primary small"><?=$a['status']==='approved'?'Unpublish':'Approve'?></button></form><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$a['id']?>"><input type="hidden" name="action" value="feature"><button class="button ghost small"><?=$a['is_featured']?'Unfeature':'Feature'?></button></form><a class="button ghost small" href="<?=e(base_url('artist-alley/manage.php?id='.(int)$a['id']))?>">Manage</a></div></td></tr><?php endforeach?></tbody></table></div><?php if(!$artists):?><p class="muted">No artist profiles yet.</p><?php endif?></section><?php app_footer();
